const upsertDriveFileAccessGranted = `-- name: UpsertDriveFileAccessGranted :one
INSERT INTO drive_file_access (
  id, organization_id, workspace_id, drive_file_id, user_id, connection_id, state, granted_at, checked_at
) VALUES (
  $1,
  $2,
  $3,
  $4,
  $5,
  $6,
  'granted',
  now(),
  now()
)
ON CONFLICT (drive_file_id, user_id) DO UPDATE
SET connection_id = EXCLUDED.connection_id,
    state = 'granted',
    granted_at = CASE
      WHEN drive_file_access.connection_id <> EXCLUDED.connection_id OR drive_file_access.state <> 'granted'
      THEN now()
      ELSE drive_file_access.granted_at
    END,
    checked_at = now()
WHERE drive_file_access.organization_id = $2
  AND drive_file_access.workspace_id = $3
RETURNING id, organization_id, workspace_id, drive_file_id, user_id, connection_id, state, granted_at, checked_at
`

